void IRQ_DMA1_I2S3_TX_Init(void)
{
	NVIC_SetPriority(DMA1_Stream7_IRQn, 1); //absolutely critical! highest prio available
	NVIC_EnableIRQ(DMA1_Stream7_IRQn);
}

void I2S_init(void)
{
	// I2S APB1 clock source selection
	// I2S1 here means I2S interfaces on APB1
	SET_FIELD_32(RCC->DCKCFGR, RCC_DCKCFGR_I2S1SRC_Msk, RCC_DCKCFGR_I2S1SRC_Pos, 0b11); // HSE or HSI
	RCC->APB1ENR |= RCC_APB1ENR_SPI3EN; // I2S3 clock enable
	RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN; // GPIOC clock enable

	/////////////////////////////////
	// SPK_SDMODE
	// PB7 pull-down output
	GPIOB->BSRR = GPIO_BSRR_BR7; // init as low
	SET_FIELD_32(GPIOB->PUPDR, GPIO_PUPDR_PUPD7_Msk, GPIO_PUPDR_PUPD7_Pos, LL_GPIO_PULL_DOWN); //pull-down
	SET_FIELD_32(GPIOB->OSPEEDR, GPIO_OSPEEDR_OSPEED7_Msk, GPIO_OSPEEDR_OSPEED7_Pos, LL_GPIO_SPEED_FREQ_LOW); //low speed
	SET_FIELD_32(GPIOB->OTYPER, GPIO_OTYPER_OT7_Msk, GPIO_OTYPER_OT7_Pos, LL_GPIO_OUTPUT_PUSHPULL); //push-pull
	SET_FIELD_32(GPIOB->MODER, GPIO_MODER_MODER7_Msk, GPIO_MODER_MODER7_Pos, LL_GPIO_MODE_OUTPUT); //output

	/////////////////////////////////
	// SPK_SD
	// PC12 AF6 I2S2_SD
	SET_FIELD_32(GPIOC->PUPDR, GPIO_PUPDR_PUPD12_Msk, GPIO_PUPDR_PUPD12_Pos, LL_GPIO_PULL_DOWN); //pull-down
	SET_FIELD_32(GPIOC->OTYPER, GPIO_OTYPER_OT12_Msk, GPIO_OTYPER_OT12_Pos, LL_GPIO_OUTPUT_PUSHPULL); //push-pull
	SET_FIELD_32(GPIOC->OSPEEDR, GPIO_OSPEEDR_OSPEED12_Msk, GPIO_OSPEEDR_OSPEED12_Pos, LL_GPIO_SPEED_FREQ_LOW); //low speed
	SET_FIELD_32(GPIOC->AFR[1], GPIO_AFRH_AFSEL12_Msk, GPIO_AFRH_AFSEL12_Pos, LL_GPIO_AF_6); //AF6 - I2S3_SD
	SET_FIELD_32(GPIOC->MODER, GPIO_MODER_MODER12_Msk, GPIO_MODER_MODER12_Pos, LL_GPIO_MODE_ALTERNATE); //alternate function

	/////////////////////////////////
	// SPK_CK
	// PC10 AF6 I2S3_CK
	SET_FIELD_32(GPIOC->PUPDR, GPIO_PUPDR_PUPD10_Msk, GPIO_PUPDR_PUPD10_Pos, LL_GPIO_PULL_DOWN); //pull-down
	SET_FIELD_32(GPIOC->OTYPER, GPIO_OTYPER_OT10_Msk, GPIO_OTYPER_OT10_Pos, LL_GPIO_OUTPUT_PUSHPULL); //push-pull
	SET_FIELD_32(GPIOC->OSPEEDR, GPIO_OSPEEDR_OSPEED10_Msk, GPIO_OSPEEDR_OSPEED10_Pos, LL_GPIO_SPEED_FREQ_LOW); //low speed
	SET_FIELD_32(GPIOC->AFR[1], GPIO_AFRH_AFSEL10_Msk, GPIO_AFRH_AFSEL10_Pos, LL_GPIO_AF_6); //AF6 - I2S3_CK
	SET_FIELD_32(GPIOC->MODER, GPIO_MODER_MODER10_Msk, GPIO_MODER_MODER10_Pos, LL_GPIO_MODE_ALTERNATE); //alternate function

	/////////////////////////////////
	// SPK_WS
	// PA15 AF6 I2S3_WS
	SET_FIELD_32(GPIOA->PUPDR, GPIO_PUPDR_PUPD15_Msk, GPIO_PUPDR_PUPD15_Pos, LL_GPIO_PULL_DOWN); //pull-down
	SET_FIELD_32(GPIOA->OTYPER, GPIO_OTYPER_OT15_Msk, GPIO_OTYPER_OT15_Pos, LL_GPIO_OUTPUT_PUSHPULL); //push-pull
	SET_FIELD_32(GPIOA->OSPEEDR, GPIO_OSPEEDR_OSPEED15_Msk, GPIO_OSPEEDR_OSPEED15_Pos, LL_GPIO_SPEED_FREQ_LOW); //low speed
	SET_FIELD_32(GPIOA->AFR[1], GPIO_AFRH_AFSEL15_Msk, GPIO_AFRH_AFSEL15_Pos, LL_GPIO_AF_6); //AF6 - I2S3_WS
	SET_FIELD_32(GPIOA->MODER, GPIO_MODER_MODER15_Msk, GPIO_MODER_MODER15_Pos, LL_GPIO_MODE_ALTERNATE); //alternate function

	/////////////////////////////////
	// I2S_3
	SET_FIELD_32(SPI3->I2SCFGR, SPI_I2SCFGR_I2SMOD_Msk, SPI_I2SCFGR_I2SMOD_Pos, 1); // I2S mode instead of default SPI mode

	// HSI 16MHz -> sample rate 16KHz
	SET_FIELD_32(SPI3->I2SPR, SPI_I2SPR_I2SDIV_Msk, SPI_I2SPR_I2SDIV_Pos, 15);
	SET_FIELD_32(SPI3->I2SPR, SPI_I2SPR_ODD_Msk, SPI_I2SPR_ODD_Pos, 1);

	SET_FIELD_32(SPI3->I2SCFGR, SPI_I2SCFGR_CKPOL_Msk, SPI_I2SCFGR_CKPOL_Pos, 1); // I2S clock steady state is high level
	SET_FIELD_32(SPI3->I2SCFGR, SPI_I2SCFGR_I2SCFG_Msk, SPI_I2SCFGR_I2SCFG_Pos, 0b10); // Master - transmit
	SET_FIELD_32(SPI3->I2SCFGR, SPI_I2SCFGR_I2SSTD_Msk, SPI_I2SCFGR_I2SSTD_Pos, 0); // I2S Phillips standard

	SET_FIELD_32(SPI3->I2SCFGR, SPI_I2SCFGR_DATLEN_Msk, SPI_I2SCFGR_DATLEN_Pos, 0); // 16-bit data length
	SET_FIELD_32(SPI3->I2SCFGR, SPI_I2SCFGR_CHLEN_Msk, SPI_I2SCFGR_CHLEN_Pos, 0); // 16-bit wide

	SET_FIELD_32(SPI3->CR2, SPI_CR2_TXDMAEN_Msk, SPI_CR2_TXDMAEN_Pos, 1); // Tx buffer DMA enable

	SET_FIELD_32(SPI3->I2SCFGR, SPI_I2SCFGR_I2SE_Msk, SPI_I2SCFGR_I2SE_Pos, 1); // I2S3 enable
}

void DMA1_I2S3_TX_init(void)
{
	RCC->AHB1ENR |= RCC_AHB1ENR_DMA1EN; // DMA1 clock enable

	SET_FIELD_32(DMA1_Stream7->CR, DMA_SxCR_EN_Msk, DMA_SxCR_EN_Pos, 0); // stream disable
	while ((DMA1_Stream7->CR & DMA_SxCR_EN_Msk) == 1); // wait until disabled

	// clear all interrupt flag registers
	DMA1_Stream7->CR = 0;
	SET_FIELD_32(DMA1->HIFCR, DMA_HIFCR_CTCIF7_Msk, DMA_HIFCR_CTCIF7_Pos, 1);
	SET_FIELD_32(DMA1->HIFCR, DMA_HIFCR_CHTIF7_Msk, DMA_HIFCR_CHTIF7_Pos, 1);
	SET_FIELD_32(DMA1->HIFCR, DMA_HIFCR_CTEIF7_Msk, DMA_HIFCR_CTEIF7_Pos, 1);
	SET_FIELD_32(DMA1->HIFCR, DMA_HIFCR_CDMEIF7_Msk, DMA_HIFCR_CDMEIF7_Pos, 1);
	SET_FIELD_32(DMA1->HIFCR, DMA_HIFCR_CFEIF7_Msk, DMA_HIFCR_CFEIF7_Pos, 1);

	DMA1_Stream7->PAR = (uint32_t)&SPI3->DR; // peripheral address
	int16_t* memPtr = SOUND_GetBufferPtr();
	if (memPtr != NULL) {
		DMA1_Stream7->M0AR = (uint32_t)memPtr; // memory address
	} else {
		return;
	}
	DMA1_Stream7->NDTR = SOUND_BUFFER_SIZE; // buffer size

	SET_FIELD_32(DMA1_Stream7->CR, DMA_SxCR_CHSEL_Msk, DMA_SxCR_CHSEL_Pos, 0b000); // channel 0
	SET_FIELD_32(DMA1_Stream7->CR, DMA_SxCR_PFCTRL_Msk, DMA_SxCR_PFCTRL_Pos, 0); // dma is flow controller
	SET_FIELD_32(DMA1_Stream7->CR, DMA_SxCR_PL_Msk, DMA_SxCR_PL_Pos, 0b11); // very high priority
	SET_FIELD_32(DMA1_Stream7->CR, DMA_SxCR_MSIZE_Msk, DMA_SxCR_MSIZE_Pos, 0b01); // 16-bit memory data size
	SET_FIELD_32(DMA1_Stream7->CR, DMA_SxCR_PSIZE_Msk, DMA_SxCR_PSIZE_Pos, 0b01); // 16-bit peripheral data size
	SET_FIELD_32(DMA1_Stream7->CR, DMA_SxCR_MINC_Msk, DMA_SxCR_MINC_Pos, 1); // memory increment mode
	SET_FIELD_32(DMA1_Stream7->CR, DMA_SxCR_DIR_Msk, DMA_SxCR_DIR_Pos, 0b01); // memory to peripheral
	SET_FIELD_32(DMA1_Stream7->CR, DMA_SxCR_CIRC_Msk, DMA_SxCR_CIRC_Pos, 1); // circular mode
	SET_FIELD_32(DMA1_Stream7->CR, DMA_SxCR_TCIE_Msk, DMA_SxCR_TCIE_Pos, 1); // transfer complete interrupt enable
	SET_FIELD_32(DMA1_Stream7->CR, DMA_SxCR_HTIE_Msk, DMA_SxCR_HTIE_Pos, 1); // half transfer complete interrupt enable

	SET_FIELD_32(DMA1_Stream7->FCR, DMA_SxFCR_DMDIS_Msk, DMA_SxFCR_DMDIS_Pos, 1); // direct mode disable (fifo enable)
	SET_FIELD_32(DMA1_Stream7->FCR, DMA_SxFCR_FTH_Msk, DMA_SxFCR_FTH_Pos, 0b11); // full fifo threshold
}


void BusFault_Init()
{
	SCB->SHCSR |= SCB_SHCSR_BUSFAULTENA_Msk |
              SCB_SHCSR_USGFAULTENA_Msk |
              SCB_SHCSR_MEMFAULTENA_Msk;
}

void BusFault_Handler(void)
{
    __BKPT(0);   // zatrzymaj debugger
    while (1);
}

void print_start()
{
 	printf_v("Welcome!\n");
}


int main(void)
{
	Flash_init();
	BusFault_Init();
	Clock_init();
	FPU_init();
	IRQ_init();
	Delay_init();
	GPIO_LCD_PAD_init();
	PAD_Init();
	GPIO_SOUND_BUTTONS_init();
	SOUND_Init();
	I2S_init();
	DMA1_I2S3_TX_init();
	IRQ_DMA1_I2S3_TX_Init();
	BATTERY_Init();
	Timer_10_init();
	printf_init();
	print_start();

	RE_Init();
	LCD_init();
	I2S_Start();
	GAME_Init();

	uint32_t timeSpentInLoopUS = 0;
	uint32_t targetFrameTimeUS = 1000000/TARGET_FRAMERATE_HZ;

	while(1)
	{
		if (timeSpentInLoopUS < targetFrameTimeUS)
		{
			uint32_t timeToDelayUS = targetFrameTimeUS - timeSpentInLoopUS;
			delayUS(timeToDelayUS);
		}

		uint32_t startLoopTime = GetTimestamp();
		
		GAME_Update();

		float mv = 0;
		BATTERY_GetVoltage(&mv);
		uint32_t mVBat = (uint32_t)mv;
		printf_v("\nmVBat: %d\n", mVBat);
		
		timeSpentInLoopUS = CalcTimeUS(startLoopTime);
	}
//#endif

    /* Loop forever */
	for(;;);
}

